117	// ---------------------------------------------------------------------------
118	// Interface definitions
119	// ---------------------------------------------------------------------------
120	
121	/** Raw query parameters accepted by GET /api/knowledge. */
122	export interface KnowledgeListParams {
123	  scope?: string;
124	  category?: string;
125	  /** Comma-separated list of tags to filter by. */
126	  tags?: string;
127	  repository_name?: string;
128	  /** Full-text search query — delegates to searchInsights when present. */
129	  query?: string;
130	  limit?: number | string;
131	  offset?: number | string;
132	}
133	
134	// ---------------------------------------------------------------------------
135	// GET /api/knowledge
136	// ---------------------------------------------------------------------------
137	
138	/**
139	 * Lists (or searches) knowledge insights stored in the ledger's `.knowledge/` directory.
140	 *
141	 * - When `query` is present, delegates to `KnowledgeStoreManager.searchInsights()`.
142	 * - Otherwise calls `KnowledgeStoreManager.listInsights()` with scope/category/tags filters.
143	 * - `scope` is validated via `InsightScope.safeParse()`; unrecognised values are silently
144	 *   treated as "no scope filter" rather than causing an error.
145	 * - `tags` is a comma-separated string that is split before being forwarded.
146	 * - `limit` and `offset` are coerced to non-negative integers; invalid/missing values
147	 *   are silently ignored (limit → undefined, offset → 0).
148	 * - `limit=0` is treated as unlimited (mapped to undefined); pass a positive integer
149	 *   to enforce a page size.
150	 */
151	export async function handleListKnowledge(
152	  ledgerRoot: string,
153	  params: KnowledgeListParams = {}
154	): Promise<Insight[]> {
155	  const manager = new KnowledgeStoreManager(ledgerRoot);
156	
157	  // Validate scope — unrecognised values fall back to undefined (no filter).
158	  const scopeResult = InsightScope.safeParse(params.scope);
159	  const scope = scopeResult.success ? scopeResult.data : undefined;
160	
161	  const category = params.category ?? undefined;
162	  const repository_name = params.repository_name ?? undefined;
163	
164	  // Split comma-separated tags; ignore empty segments.
165	  const tags =
166	    params.tags && params.tags.trim().length > 0
167	      ? params.tags
168	          .split(',')
169	          .map((t) => t.trim())
170	          .filter((t) => t.length > 0)
171	      : undefined;
172	
173	  // Coerce pagination params.
174	  const limitRaw = params.limit !== undefined ? Math.floor(Number(params.limit)) : NaN;
175	  const limit = !isNaN(limitRaw) && limitRaw > 0 ? limitRaw : undefined;
176	
177	  const offsetRaw = params.offset !== undefined ? Math.floor(Number(params.offset)) : NaN;
178	  const offset = !isNaN(offsetRaw) && offsetRaw >= 0 ? offsetRaw : 0;
179	
180	  if (params.query && params.query.trim().length > 0) {
181	    return manager.searchInsights(params.query.trim(), { scope, repository_name, category, tags, limit, offset });
182	  }
183	
184	  return manager.listInsights({ scope, category, tags, repository_name, limit, offset });
185	}
186	
187	// ---------------------------------------------------------------------------
188	// PATCH /api/knowledge/:id
189	// ---------------------------------------------------------------------------
190	
191	/**
192	 * Updates an existing knowledge insight identified by its numeric ID.
193	 *
194	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
195	 * for non-integer, zero, or floating-point strings). Validates the request body
196	 * via `KnowledgeUpdateBodySchema` (throws VALIDATION_ERROR for unknown fields or
197	 * type mismatches). Extracts `scope` and `repository_name` discriminator fields to
198	 * scope the update to the correct store.
199	 *
200	 * `superseded_by: null` in the body is mapped to `undefined` so the field is
201	 * cleared (removed) on the stored insight.
202	 *
203	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
204	 *
205	 * @param ledgerRoot  Absolute path to the central ledger root.
206	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
207	 * @param body        Parsed request body (any shape — validated here).
208	 * @returns The updated Insight.
209	 */
210	export async function handleUpdateKnowledge(
211	  ledgerRoot: string,
212	  rawId: string,
213	  body: unknown
214	): Promise<Insight> {
215	  const id = parseKnowledgeId(rawId);
216	
217	  const parseResult = KnowledgeUpdateBodySchema.safeParse(body);
218	  if (!parseResult.success) {
219	    validationError('Invalid knowledge update body.', parseResult.error.issues);
220	  }
221	
222	  const { scope, repository_name, superseded_by, ...rest } = parseResult.data;
223	
224	  // Map superseded_by: null → undefined so the field is cleared on the stored insight.
225	  const updates: Parameters<KnowledgeStoreManager['updateInsight']>[1] = {
226	    ...rest,
227	    ...(superseded_by === null ? { superseded_by: undefined } : superseded_by !== undefined ? { superseded_by } : {}),
228	  };
229	
230	  const manager = new KnowledgeStoreManager(ledgerRoot);
231	
232	  try {
233	    return await manager.updateInsight(id, updates, { scope, repository_name });
234	  } catch (err) {
235	    const msg = err instanceof Error ? err.message : String(err);
236	    if (msg.includes('not found')) {
237	      throw new ApiError('NOT_FOUND', 'Insight not found.');
238	    }
239	    throw err;
240	  }
241	}
242	
243	// ---------------------------------------------------------------------------
244	// DELETE /api/knowledge/:id
245	// ---------------------------------------------------------------------------
246	
247	/**
248	 * Deletes an existing knowledge insight identified by its numeric ID.
249	 *
250	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
251	 * for non-integer, zero, or floating-point strings). Requires `scope` as a
252	 * query parameter; when `scope === 'repository'`, `repository_name` is also required
253	 * (throws VALIDATION_ERROR if absent). Scopes the deletion to the correct store
254	 * to prevent accidental cross-scope deletion when the same numeric ID exists in
255	 * multiple stores.
256	 *
257	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
258	 *
259	 * @param ledgerRoot      Absolute path to the central ledger root.
260	 * @param rawId           Raw ID string from the URL parameter (e.g. "42").
261	 * @param scope           Required scope query parameter ('global' or 'repository').
262	 * @param repository_name Required when scope is 'repository'; the repository name.
263	 * @returns `null` — consistent with other delete handlers.
264	 */
265	export async function handleDeleteKnowledge(
266	  ledgerRoot: string,
267	  rawId: string,
268	  scope: string | undefined,
269	  repository_name?: string
270	): Promise<null> {
271	  const id = parseKnowledgeId(rawId);
272	
273	  // Validate scope — required and must be a recognised InsightScope value.
274	  const scopeResult = InsightScope.safeParse(scope);
275	  if (!scopeResult.success) {
276	    validationError('scope query parameter is required and must be "global" or "repository".');
277	  }
278	  const validatedScope = scopeResult.data;
279	
280	  // repository_name is required when scope === 'repository'.
281	  if (validatedScope === 'repository' && !repository_name) {
282	    validationError('repository_name query parameter is required when scope is "repository".');
283	  }
284	
285	  const manager = new KnowledgeStoreManager(ledgerRoot);
286	
287	  try {
288	    await manager.deleteInsight(id, { scope: validatedScope, repository_name });
289	  } catch (err) {
290	    const msg = err instanceof Error ? err.message : String(err);
291	    if (msg.includes('not found')) {
292	      throw new ApiError('NOT_FOUND', 'Insight not found.');
293	    }
294	    throw err;
295	  }
296	
297	  return null;
298	}
299	
300	// ---------------------------------------------------------------------------

301	// POST /api/knowledge/:id/promote
302	// ---------------------------------------------------------------------------
303	
304	/**
305	 * Promotes a repository-scoped insight to global scope using the atomic
306	 * KnowledgeStoreManager.moveInsight() method.
307	 *
308	 * The returned insight is the newly created global-scoped copy — it has a
309	 * **different numeric ID** than the original (assigned by the global store's
310	 * `next_id` counter). The frontend must match by pre-promote ID, not the new ID.
311	 *
312	 * @param ledgerRoot      Absolute path to the central ledger root.
313	 * @param rawId           Raw ID string from the URL parameter (e.g. "42").
314	 * @param scope           Source scope — must be "repository" (global insights cannot be promoted).
315	 * @param repository_name Required when scope is "repository"; the source repository name.
316	 * @returns The newly created global Insight.
317	 * @throws ApiError VALIDATION_ERROR if scope is not "repository", or insight is already global.
318	 * @throws ApiError NOT_FOUND if no matching insight exists in the specified scope.
319	 */
320	export async function handlePromoteKnowledge(
321	  ledgerRoot: string,
322	  rawId: string,
323	  scope: string | undefined,
324	  repository_name?: string
325	): Promise<Insight> {
326	  const id = parseKnowledgeId(rawId);
327	
328	  // Validate scope — must be 'repository' (global insights are already global).
329	  const scopeResult = InsightScope.safeParse(scope);
330	  if (!scopeResult.success) {
331	    validationError('scope query parameter is required and must be "global" or "repository".');
332	  }
333	  const validatedScope = scopeResult.data;
334	
335	  if (validatedScope === 'global') {
336	    validationError('Insight is already global and cannot be promoted.');
337	  }
338	
339	  // repository_name is required when scope === 'repository'.
340	  if (!repository_name) {
341	    validationError('repository_name query parameter is required when scope is "repository".');
342	  }
343	
344	  const manager = new KnowledgeStoreManager(ledgerRoot);
345	
346	  try {
347	    return await manager.moveInsight(
348	      id,
349	      { scope: validatedScope, repository_name },
350	      'global'
351	    );
352	  } catch (err) {
353	    const msg = err instanceof Error ? err.message : String(err);
354	    if (msg.toLowerCase().includes('not found')) {
355	      throw new ApiError('NOT_FOUND', 'Insight not found.');
356	    }
357	    throw err;
358	  }
359	}
360	
361	// ---------------------------------------------------------------------------
362	// POST /api/knowledge/:id/move
363	// ---------------------------------------------------------------------------
364	
365	/**
366	 * Moves an insight from one scope/repository to a different repository using the
367	 * atomic KnowledgeStoreManager.moveInsight() method.
368	 *
369	 * Supports two move variants:
370	 * - global → repository: moves the global insight into a named repository store
371	 * - repository → repository: moves a repository insight to a different repository
372	 *
373	 * The returned insight is the newly created copy — it has a **different numeric
374	 * ID** (assigned by the target store's `next_id` counter).
375	 *
376	 * @param ledgerRoot  Absolute path to the central ledger root.
377	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
378	 * @param body        Parsed request body (validated against KnowledgeMoveBodySchema).
379	 * @returns The newly created Insight in the target repository store.
380	 * @throws ApiError VALIDATION_ERROR when source and destination are identical, body is invalid,
381	 *   or the destination name fails PROJECT_SLUG_REGEX.
382	 * @throws ApiError NOT_FOUND when no matching insight exists in the source scope.
383	 */
384	export async function handleMoveKnowledge(
385	  ledgerRoot: string,
386	  rawId: string,
387	  body: unknown
388	): Promise<Insight> {
389	  const id = parseKnowledgeId(rawId);
390	
391	  const parseResult = KnowledgeMoveBodySchema.safeParse(body);
392	  if (!parseResult.success) {
393	    validationError('Invalid knowledge move body.', parseResult.error.issues);
394	  }
395	
396	  const { source_scope, source_repository_name, repository_name } = parseResult.data;
397	
398	  // Require source_repository_name when source_scope is 'repository'.
399	  if (source_scope === 'repository' && !source_repository_name) {
400	    validationError('source_repository_name is required when source_scope is "repository".');
401	  }
402	
403	  // Validate that source and destination are not identical.
404	  // global → repository always changes scope, so no identity check is needed for that case.
405	  if (source_scope === 'repository' && source_repository_name === repository_name) {
406	    validationError('Source and destination repository are identical; nothing to move.');
407	  }
408	
409	  const manager = new KnowledgeStoreManager(ledgerRoot);
410	
411	  try {
412	    return await manager.moveInsight(
413	      id,
414	      { scope: source_scope, repository_name: source_repository_name },
415	      'repository',
416	      repository_name
417	    );
418	  } catch (err) {
419	    const msg = err instanceof Error ? err.message : String(err);
420	    if (msg.toLowerCase().includes('not found')) {
421	      throw new ApiError('NOT_FOUND', 'Insight not found.');
422	    }
423	    throw err;
424	  }
425	}

  1	import { readFile, readdir } from 'fs/promises';
  2	import { join } from 'path';
  3	import type { Dirent } from 'fs';
  4	import {
  5	  KnowledgeStoreSchema,
  6	  InsightSchema,
  7	  PROJECT_SLUG_REGEX,
  8	  type KnowledgeStore,
  9	  type Insight,
 10	  type InsightScope,
 11	} from '../schema/knowledge.js';
 12	import { atomicWriteJson } from './atomic-writer.js';
 13	import { withLock } from './file-lock.js';
 14	import { now } from '../utils/timestamp.js';
 15	
 16	/**
 17	 * Manages the `.knowledge/` directory, providing all CRUD operations for
 18	 * insights with atomic writes, file locking, and in-memory search/filter logic.
 19	 *
 20	 * Storage layout (relative to `ledgerRoot`):
 21	 *   .knowledge/
 22	 *     .lock                              — lock file created by withLock
 23	 *     global-insights.json              — insights with scope: 'global'
 24	 *     {repository_name}-insights.json   — insights scoped to a specific repository
 25	 *
 26	 * Locking strategy:
 27	 *   - All read-modify-write sequences (addInsight, updateInsight, deleteInsight)
 28	 *     acquire a single lock on knowledgeDir() for the entire operation.
 29	 *   - All writes use atomicWriteJson() — write-to-temp-then-rename.
 30	 *   - Pure reads (readGlobalStore, readRepositoryStore, searchInsights, listInsights)
 31	 *     do not acquire a lock, consistent with the LedgerStore pattern.
 32	 *
 33	 * scope === 'repository' + repository_name constraint:
 34	 *   The Zod schema accepts repository_name as optional to remain context-free.
 35	 *   This class enforces the constraint: addInsight() throws if scope is 'repository'
 36	 *   and repository_name is absent.
 37	 */
 38	export class KnowledgeStoreManager {
 39	  public readonly ledgerRoot: string;
 40	
 41	  constructor(ledgerRoot: string) {
 42	    this.ledgerRoot = ledgerRoot;
 43	  }
 44	
 45	  // ==================== Path Helpers ====================
 46	
 47	  knowledgeDir(): string {
 48	    return join(this.ledgerRoot, '.knowledge');
 49	  }
 50	
 51	  globalStorePath(): string {
 52	    return join(this.knowledgeDir(), 'global-insights.json');
 53	  }
 54	
 55	  /**
 56	   * Returns the file path for a repository-scoped insights store.
 57	   *
 58	   * @param repoName - Repository name (used to derive the filename)
 59	   * @throws Error if repoName is 'global' (reserved name)
 60	   * @throws Error if repoName contains unsafe characters (path traversal guard)
 61	   */
 62	  repositoryStorePath(repoName: string): string {
 63	    if (repoName === 'global') {
 64	      throw new Error("'global' is a reserved name and cannot be used as a repository name.");
 65	    }
 66	    this._validateSlug(repoName);
 67	    return join(this.knowledgeDir(), `${repoName}-insights.json`);
 68	  }
 69	
 70	  // ==================== Read Methods ====================
 71	
 72	  /**
 73	   * Reads and validates the global insights store.
 74	   * Returns a valid empty KnowledgeStore if the file does not yet exist.
 75	   *
 76	   * @throws Error if the file exists but contains malformed JSON or fails schema validation
 77	   */
 78	  async readGlobalStore(): Promise<KnowledgeStore> {
 79	    return this._readStore(this.globalStorePath());
 80	  }
 81	
 82	  /**
 83	   * Reads and validates a repository-scoped insights store.
 84	   * Returns a valid empty KnowledgeStore if the file does not yet exist.
 85	   *
 86	   * @param repoName - Repository name (used to derive the filename)
 87	   * @throws Error if the file exists but contains malformed JSON or fails schema validation
 88	   */
 89	  async readRepositoryStore(repoName: string): Promise<KnowledgeStore> {
 90	    return this._readStore(this.repositoryStorePath(repoName));
 91	  }
 92	
 93	  // ==================== Write Methods ====================
 94	
 95	  /**
 96	   * Writes the global insights store atomically under a lock.
 97	   * Validates the data against KnowledgeStoreSchema before writing.
 98	   *
 99	   * @param data - Store data to persist
100	   * @throws Error if validation fails or write fails

101	   * @warning Do NOT call this method from inside a withLock(knowledgeDir, ...) callback.
102	   *   The CRUD methods (addInsight, updateInsight, deleteInsight) intentionally bypass
103	   *   this method and call atomicWriteJson directly to avoid nested lock acquisition,
104	   *   which would deadlock. This method is safe only at the top level.
