436	  /**
437	   * Deletes an insight by numeric ID.
438	   *
439	   * When `filter.scope` and/or `filter.repository_name` are provided the search is
440	   * restricted to the matching store(s), preventing accidental global-insight
441	   * deletion when the same numeric ID exists in multiple stores. Without a
442	   * filter, all stores are scanned (original behaviour — preserved for
443	   * backwards compatibility).
444	   *
445	   * The entire read-modify-write sequence runs under a single lock.
446	   *
447	   * @param id - Numeric insight id
448	   * @param filter - Optional scope/repository_name filter to restrict which store is searched
449	   * @throws Error if no insight with the given id exists in the filtered stores
450	   */

451	  async deleteInsight(id: number, filter?: { scope?: InsightScope; repository_name?: string }): Promise<void> {
452	    await withLock(this.knowledgeDir(), async () => {
453	      const storePaths = await this._storePathsForFilter(filter);
454	
455	      for (const storePath of storePaths) {
456	        const store = await this._readStore(storePath);
457	        const idx = store.insights.findIndex((i) => i.id === id);
458	
459	        if (idx === -1) continue;
460	
461	        store.insights.splice(idx, 1);
462	        store.last_updated = now();
463	
464	        const validated = KnowledgeStoreSchema.parse(store);
465	        await atomicWriteJson(storePath, validated);
466	        return;
467	      }
